import React from 'react';
import './BikeList.css';
function BikeList() {
  return (
    <div>
      <h2>Available Bikes</h2>
      <ul>
        <li>Honda Activa 6G - ₹72,000</li>
        <li>Royal Enfield Classic 350 - ₹1,95,000</li>
        <li>TVS Apache RTR 160 - ₹1,25,000</li>
      </ul>
    </div>
  );
}

export default BikeList;
